import{densityReading,finalStates}from './mat1-models.js?v=20261023-physicscomplete01';
const ink='#faf5ed',mint='#a9cabe',coral='#f18d77',dim='#adbecb';const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=x=>Number(Number(x).toFixed(3));
const T=(x,y,s,n=18,c=ink)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;
const L=(x,y,u,v,c=dim,w=3)=>`<path d="M${x} ${y}L${u} ${v}" fill="none" stroke="${c}" stroke-width="${w}"/>`;
const B=(x,y,w,h,c='#26485b')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="14" fill="${c}" stroke="${dim}"/>`;
const D=(x,y,s='+',r=26)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${s==='+'?'url(#mat1-warm)':'url(#mat1-cool)'}" stroke="#d7e3e7" stroke-width="1.2"/>`+T(x,y+7,s,24,s==='+'?'#492e27':'#153246');
export const matterSVG=(body,label)=>`<svg viewBox="0 0 560 480" role="img" aria-label="${esc(label)}"><defs><radialGradient id="mat1-warm" cx="30%" cy="25%"><stop stop-color="#fff1d9"/><stop offset=".45" stop-color="#e9ac91"/><stop offset="1" stop-color="#9a594f"/></radialGradient><radialGradient id="mat1-cool" cx="30%" cy="25%"><stop stop-color="#f0fff8"/><stop offset=".45" stop-color="#a2c9c0"/><stop offset="1" stop-color="#49777d"/></radialGradient></defs>${body}</svg>`;
function arrow(x,y,u,v,c=coral,w=3){let a=Math.atan2(v-y,u-x),h=10;return L(x,y,u,v,c,w)+`<path d="M${u-h*Math.cos(a-.48)} ${v-h*Math.sin(a-.48)}L${u} ${v}L${u-h*Math.cos(a+.48)} ${v-h*Math.sin(a+.48)}" fill="none" stroke="${c}" stroke-width="${w}"/>`;}
export function chargeFigure({a='B',b='2',progress=1,movie=false,revealed=true}={}){let n=movie?3:+b,p=movie?Math.max(0,Math.min(1,(progress-.08)/.8)):(revealed?1:0),gain=a,source=gain==='B'?'A':'B',gx=gain==='A'?140:420,sx=gain==='A'?420:140,arrived=Math.min(n,Math.floor(p*n)),inTransit=movie&&p>0&&p<1&&p*n%1>0,body=T(280,29,'Move electrons · conserve total charge',24)+B(40,87,200,255)+B(320,87,200,255)+T(140,69,'Surface A',21)+T(420,69,'Surface B',21);
for(let x of[140,420]){for(let j=0;j<8;j++)body+=D(x-66+(j%4)*44,122+Math.floor(j/4)*43,'+',14);let remaining=8-(x===sx?arrived+(inTransit?1:0):0);for(let j=0;j<remaining;j++)body+=D(x-66+(j%4)*44,231+Math.floor(j/4)*43,'−',13);if(x===gx)for(let j=0;j<arrived;j++)body+=D(x-66+j*35,316,'−',12);}
if(inTransit){let f=(p*n)%1;body+=D(sx+(gx-sx)*f,359,'−',11);}body+=arrow(sx,366,gx,366,mint)+T(280,398,'Electron transfer: '+source+' → '+gain,21)+T(280,433,revealed||movie?gain+': '+(8+arrived)+' electrons · '+source+': '+(8-arrived-(inTransit?1:0))+(inTransit?' · 1 in transit':''):'Predict gaining surface’s electron count',20)+T(280,465,'8 positive markers each · 16 electrons across pair · schematic counts',14);
return matterSVG(body,`Two surfaces each start with8 positive and8 negative markers. ${arrived} electrons arrived from${source} to${gain}; ${inTransit?'1 electron in transit, excluded from the source count.':''} Total16 electrons conserved. ${gain} is negative after gaining; ${source} is positive after losing. Protons stay in place. Timing symbolic.`);}
export function forcesFigure({a,b,state='0',progress=0,movie=false,revealed=true}={}){let pairs=[['positive','positive'],['positive','negative'],['negative','negative']],pair=pairs[Number(state)%3]||pairs[0];a=a||pair[0];b=b||pair[1];if(movie){a='positive';b=progress<.5?'positive':'negative';}let repel=a===b,shift=movie?12*Math.sin(Math.PI*((progress*2)%1)):0,x=180+(repel?-shift:shift),u=380+(repel?shift:-shift);let body=T(280,30,'Like signs repel · unlike signs attract',23)+L(100,82,460,82,dim,4)+L(180,82,x,219)+L(380,82,u,219)+D(x,249,a==='positive'?'+':'−',44)+D(u,249,b==='positive'?'+':'−',44)+T(x,326,a,20)+T(u,326,b,20);
if(revealed||movie)body+=arrow(x+(repel?-50:50),249,x+(repel?-100:90),249)+arrow(u+(repel?50:-50),249,u+(repel?100:-90),249)+T(280,384,repel?'REPULSION · move apart':'ATTRACTION · move together',23);
else body+=T(280,384,'Predict the force directions',23);
body+=T(280,424,'Force across a gap · objects do not touch',18)+T(280,465,'Arrow length/displacement qualitative · no force or acceleration calibration',13);
return matterSVG(body,`${a} left object and ${b} right object separated by a gap. ${revealed||movie?(repel?'Repulsive forces point apart.':'Attractive forces point towards each other.'):'Force response concealed until prediction.'} Symbolic suspended objects, no measured force; attraction alone does not prove opposite net charge.`);}
export function fieldFigure({a='positive',b='near',progress=0,movie=false,revealed=true,step=0}={}){let sign=a==='positive'?'+':'−',negative=a==='negative',r=b==='near'?90:180,stage=movie?Math.min(3,Math.floor(progress*4)):0;let body=T(280,29,movie?'Build charge → conducting gap → discharge':'Radial field · positive test-charge convention',22);if(movie){let strength=stage===0?.35+progress:stage===3?.28:1;body+=D(135,238,'−',45)+D(425,238,'+',45)+T(135,316,'Excess electrons',18)+T(425,316,'Electron deficit',18);for(let j=0;j<5;j++)body+=L(180,195+j*20,380,195+j*20,dim,Math.max(1,4*strength));if(stage===1||stage===2)body+=`<path d="M180 239l32 -16 25 31 22 -27 30 25 30 -30 25 22 35 -6" fill="none" stroke="${coral}" stroke-width="4"/>`;if(stage===2)for(let j=0;j<3;j++)body+=D(190+((progress*4+j/3)%1)*180,237,'−',9);body+=T(280,370,['Charge builds: field grows','Strong field: air gap can conduct','Charge flows through conducting gap','Imbalance decreases: field weakens'][stage],21)+T(280,420,'Air conduction and charge transfer are schematic',16)+T(280,463,'Not a high-voltage experiment · no real breakdown threshold/timing',14);return matterSVG(body,`Spark worked sequence: ${['charge builds and field grows','air gap becomes conducting','electrons flow from negative towards positive','charge imbalance and field decrease'][stage]}. Field lines are representations, not particle tracks. No numerical voltage, field threshold or discharge timing predicted.`);}
body+=D(280,242,sign,44);for(let j=0;j<12;j++){let ang=2*Math.PI*j/12,cs=Math.cos(ang),sn=Math.sin(ang),x=280+55*cs,y=242+55*sn,u=280+190*cs,v=242+190*sn;if(revealed)body+=negative?arrow(u,v,x,y,mint,2):arrow(x,y,u,v,mint,2);else body+=L(x,y,u,v,dim,1);}
body+=D(280+r,242,'+',16)+T(280+r,287,'test +',15)+T(280,60,a+' sphere · '+b+' test position',18)+T(280,446,revealed?(negative?'Inward':'Outward')+' force · '+(b==='near'?'stronger':'weaker'):'Predict direction and relative strength',21)+T(280,473,'Fixed source/test magnitudes · radial lines are not electron trajectories',13);
return matterSVG(body,`Isolated${a} source sphere with a positive test charge${b}. ${revealed?`Radial arrows${negative?'inward':'outward'}; force relatively${b==='near'?'stronger':'weaker'}.`:'Arrowheads/strength concealed until reveal.'} Field is strongest close to source. Test position/sphere not to scale. A negative test charge would feel force opposite to field arrows.`);}
function cylinder(x,y,level,label){let h=220,base=y+h,water=base-level*2.1;let body=`<path d="M${x} ${y}V${base}H${x+100}V${y}" fill="none" stroke="${ink}" stroke-width="3"/><path d="M${x+2} ${water}H${x+98}V${base-2}H${x+2}Z" fill="#8ab6c5" opacity=".45"/>`+L(x+2,water,x+98,water,mint,2);for(let v=10;v<=90;v+=10){let yy=base-v*2.1;body+=L(x-8,yy,x+10,yy,dim,1)+T(x-27,yy+4,v,12);}return body+T(x+50,y-18,label,18);}
export function densityFigure({a='irregular',b='A',progress=0,movie=false,revealed=true}={}){if(movie){a='irregular';b='A';}let d=densityReading(a,b),body=T(280,29,'Density = mass / volume',25);if(a==='irregular'){let level=movie&&progress<.25?d.before:d.after;body+=cylinder(330,116,level,'Measuring cylinder / cm³')+B(44,142,175,120)+T(130,178,'Balance',21)+T(130,224,d.mass+' g',26)+`<path d="M356 245l41 -15 19 27 -13 34 -42 -2Z" fill="url(#mat1-warm)" stroke="${ink}" transform="translate(0 ${movie&&progress<.25?-170:0})"/>`+T(130,320,'Before '+d.before+' cm³',21)+T(130,354,'After '+d.after+' cm³',21)+T(280,402,'Object volume = '+d.after+' − '+d.before+' = '+d.volume+' cm³',20);}
else if(a==='regular'){body+=`<path d="M160 187l160 -48 91 73 -154 53Z" fill="#e3ac96"/><path d="M160 187l97 78v92l-97 -81Z" fill="#aa6d60"/><path d="M257 265l154 -53v90l-154 55Z" fill="#cf9580"/>`+T(280,102,'Regular cuboid · sample '+b,21)+T(280,391,d.dimensions.join(' × ')+' cm dimensions · '+d.mass+' g',23)+T(280,429,'Volume '+d.dimensions.join(' × ')+' = '+d.volume+' cm³',20);}
else{body+=cylinder(330,117,d.volume,'Liquid volume / cm³')+B(35,140,210,155)+T(140,174,'Container mass account',18)+T(140,220,'Empty '+d.empty+' g',21)+T(140,258,'Filled '+d.filled+' g',21)+T(280,400,'Liquid mass = '+d.filled+' − '+d.empty+' = '+d.mass+' g',22);}
body+=T(280,461,movie&&progress<.75?(progress<.25?'Before immersion: '+d.before+' cm³':'After − before = '+d.volume+' cm³'):revealed?d.mass+' / '+d.volume+' = '+fmt(d.value)+' g/cm³':'Predict density / g/cm³',23);return matterSVG(body,`${a} sample${b}: ${a==='regular'?'dimensions'+d.dimensions.join(' by ')+'cm':a==='irregular'?'cylinder before'+d.before+' and after'+d.after+'cm cubed':'container empty'+d.empty+'g, filled'+d.filled+'g'}. Sample mass${d.mass}g, volume${d.volume}cm cubed. ${revealed?'Density'+fmt(d.value)+'g/cm cubed.':'Density output concealed until reveal.'} Original illustrative readings, not an actual experiment. No bubbles/absorption; images not scale measurements.`);}
export function statesFigure({a='melt',b='20',progress=0,movie=false,revealed=true,state='0',step=0}={}){let route=['solid','liquid','gas','liquid','solid'],from={melt:'solid',freeze:'liquid',vaporise:'liquid',condense:'gas',sublime:'solid'},s=movie?route[Math.min(4,Math.floor(progress*5))]:finalStates[a]||'solid',showFinal=revealed||movie,display=showFinal?s:from[a],time=movie?progress*10:0,body=T(280,29,'Sealed sample · same 12 particle markers',23)+B(61,89,438,288,'#1d394d')+T(280,68,showFinal?display.toUpperCase():'Initial '+display+' → predict final state',21);
for(let j=0;j<12;j++){let col=j%4,row=Math.floor(j/4),x,y;if(display==='solid'){x=210+col*45+2*Math.sin(time*6+j);y=227+row*44+2*Math.cos(time*6+j);}else if(display==='liquid'){x=130+((col*70+row*19+time*12)%290);y=262+row*31+5*Math.sin(j+time*2);}else{x=91+((j*79+time*(17+j))%380);y=120+((j*47+time*(13+j))%215);}body+=D(x,y,'',14);}
body+=T(280,411,movie?'Teaching cycle: solid → liquid → gas → liquid → solid':a+' · '+b+' g initially sealed',20)+T(280,447,showFinal?b+' g total · no particles lost':'Predict final state and whether mass changes',21)+T(280,474,'Fixed particle size · symbolic positions/time · no transition temperatures',13);
return matterSVG(body,`${showFinal?display:'Initial'+display};12 identical particle markers within a sealed boundary. ${b}g total conserved. ${display==='solid'?'Particles vibrate around fixed sites.':display==='liquid'?'Particles stay close and move past one another.':'Particles spread widely through the container.'} ${showFinal?'Final state shown.':'Final state concealed until reveal.'} Schematic, not actual molecular trajectories, phase density values or transition timing.`);}
export function matterFigure(o={}){if(o.concealed)return matterSVG(T(280,235,'Predict, then reveal the evidence',24),'Evidence concealed until prediction');if(o.kind==='fields-sequence')return fieldFigure({...o,movie:true,progress:Math.min(.999,(o.step||0)/4)});if(o.kind==='states-sequence'){let seq=['solid','liquid','gas','liquid','solid'];return statesFigure({...o,movie:true,progress:(Math.max(0,(o.step||1)-1)+.1)/5});}let k=(o.kind||'charge').replace(/-(model|data|sequence)$/,'');if(k==='charge')return chargeFigure(o);if(k==='forces')return forcesFigure(o);if(k==='fields')return fieldFigure({...o,a:o.a||(String(o.state)==='1'?'negative':'positive')});if(k==='density')return densityFigure(o);return statesFigure(o);}
